-- SISTEMA DE INVENTARIOS LWI - FASE 1
-- Carga reproducible desde LWI 0826.xlsm, hoja Stock (617 productos).
-- Ejecutar DESPUES de 01_crear_estructura_fase1.sql.
-- No importa SALDOS, COSTOS, ENTRADAS ni SALIDAS. No actualiza productos existentes.
-- Conservar variantes tal cual aparecen en el Excel; discrepancias en CSV adjunto.

BEGIN;
CREATE TEMP TABLE stg_fase1_productos (
    codigo VARCHAR(80) NOT NULL,
    nombre VARCHAR(255) NOT NULL,
    categoria VARCHAR(200) NOT NULL,
    fila_excel INTEGER NOT NULL
) ON COMMIT DROP;


-- No normalizar ni fusionar categorias que presenten diferencias en el Excel.
SELECT DISTINCT s.categoria,
       (s.categoria = 'REPUESTOS Y ACCESORIOS LS400 y LS301')
FROM stg_fase1_productos s
ON CONFLICT DO NOTHING;

-- No inventar unidad de medida, costo, marca ni caducidad al importar.
    codigo, nombre, categoria_id, fuente_importacion, pendiente_revision
)
SELECT s.codigo, s.nombre, c.id, 'LWI 0826.xlsm - Stock', TRUE
FROM stg_fase1_productos s
JOIN public.categorias c ON c.nombre = s.categoria
ON CONFLICT DO NOTHING;

-- Los conteos son informativos; el numero exacto depende de si ya existian registros.
SELECT
    (SELECT count(*) FROM stg_fase1_productos) AS filas_origen,
    (SELECT count(*) FROM public.productos WHERE fuente_importacion='LWI 0826.xlsm - Stock') AS productos_importados_de_este_origen,
    (SELECT count(*) FROM public.categorias WHERE nombre IN (SELECT categoria FROM stg_fase1_productos)) AS categorias_del_archivo;

COMMIT;
